function indentOf(line: string): number {
  return (line.match(/^\s*/)?.[0] ?? '').replace(/\t/g, '    ').length;
}

/** Non-blank lines indented under `lines[index]` (nested bullets, tables, paragraphs), blank lines skipped. */
function nestedLines(lines: string[], index: number): string[] {
  const own = indentOf(lines[index]);
  const nested: string[] = [];
  for (let i = index + 1; i < lines.length; i += 1) {
    if (!lines[i].trim()) continue;
    if (indentOf(lines[i]) <= own) break;
    nested.push(lines[i]);
  }
  return nested;
}

/** Field lines with no value on the line and nothing indented below them. */
function unansweredFieldLines(lines: string[]): Set<number> {
  const unanswered = new Set<number>();
  lines.forEach((line, i) => {
    if (EMPTY_FIELD.test(line) && nestedLines(lines, i).length === 0) unanswered.add(i);
  });
  return unanswered;
}

/** The answer of the field at `lines[index]`: text after its label (and hint), plus any nested lines. */
function fieldValue(lines: string[], index: number): string {
  const line = lines[index];
  const m = line.match(FIELD_LINE);
  let inline: string;
  if (!m) {
    inline = line.split(':').slice(1).join(':');
  } else if (m[1].trim().endsWith(':')) {
    inline = m[2]; // `- **Label:** value`
  } else {
    // `- **Label** (hint, may contain "a: b" or nested parens): value`
    inline = m[2].replace(/^\s*(?:\((?:[^()]|\([^()]*\))*\))?\s*:?/, '');
  }
  return [inline, ...nestedLines(lines, index)].join('\n').trim();
}

function tiersIn(text: string): RiskTier[] {
  return RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(text));
}

function extractTier(body: string): RiskTier | null {
  // Skip the template's enum hint "(prohibited / high / limited / minimal)".
  const clean = (text: string) => text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
  const lines = body.split(/\r?\n/);
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const fieldIndex = lines.findIndex((l) => TIER_FIELD.test(l) || /^\s*[-*]\s*tier\b/i.test(l));
  if (fieldIndex === -1) {
    const cleaned = clean(body);
    const found = tiersIn(cleaned);
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      const inValue = tiersIn(cleaned.split(':').slice(1).join(':'));
      if (inValue.length === 1) return inValue[0];
    }
    return null;
  }

  const fieldLine = clean(lines[fieldIndex]);
  const nested = nestedLines(lines, fieldIndex).map(clean);
  const found = tiersIn([fieldLine, ...nested].join('\n'));
  if (found.length === 1) return found[0];
  if (found.length > 1) {
    // Ambiguous mention; the value after the colon on the field line wins, else the
    // first nested line that names a tier (e.g. "limited" above "- not high because ...").
    for (const candidate of [fieldLine.split(':').slice(1).join(':'), ...nested]) {
      const inValue = tiersIn(candidate);
      if (inValue.length === 1) return inValue[0];
      if (inValue.length > 1) break;
    }
  }
  return null;
}

function answeredText(body: string): string {
  const lines = body.split(/\r?\n/);
  const unanswered = unansweredFieldLines(lines);
  return lines
    .filter((_, i) => !unanswered.has(i))
    .join('\n')
    .trim();
}

function quote(line: string): string {
  const text = line.trim();
  return text.length > MAX_QUOTE ? `${text.slice(0, MAX_QUOTE - 1)}…` : text;
}

