import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** The marker `frai-gate draft` leaves wherever a human decision is still owed. */
const NEEDS_HUMAN_INPUT = /\bNEEDS\s+HUMAN\s+INPUT\b/;
/**
 * A field line with nothing after its label, in either style:
 * `- **Retention**:` / `- **Retention** (hint):` or `- **Retention:**`.
 * It still counts as answered when indented content follows (see unansweredFieldLines).
 */
const EMPTY_FIELD = /^\s*[-*]\s*\*\*(?:[^*]+\*\*.*:|[^*]+:\*\*)\s*$/;
/** A bold-labelled field line: captures the label and everything after it. */
const FIELD_LINE = /^\s*[-*]\s*\*\*([^*]+)\*\*(.*)$/;
const TIER_FIELD = /\*\*\s*(?:risk\s+)?tier\s*(?:\([^)]*\))?\s*:?\s*\*\*/i;
const SIGNOFF_FIELD = /^\s*[-*]\s*\*\*\s*sign[- ]?off\b[^*]*\*\*/i;
const MAX_QUOTE = 160;

interface Section {
  heading: string;
  body: string;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function indentOf(line: string): number {
  return (line.match(/^\s*/)?.[0] ?? '').replace(/\t/g, '    ').length;
}

/** Non-blank lines indented under `lines[index]` (nested bullets, tables, paragraphs), blank lines skipped. */
function nestedLines(lines: string[], index: number): string[] {
  const own = indentOf(lines[index]);
  const nested: string[] = [];
  for (let i = index + 1; i < lines.length; i += 1) {
    if (!lines[i].trim()) continue;
    if (indentOf(lines[i]) <= own) break;
    nested.push(lines[i]);
  }
  return nested;
}

/** Field lines with no value on the line and nothing indented below them. */
function unansweredFieldLines(lines: string[]): Set<number> {
  const unanswered = new Set<number>();
  lines.forEach((line, i) => {
    if (EMPTY_FIELD.test(line) && nestedLines(lines, i).length === 0) unanswered.add(i);
  });
  return unanswered;
}

/** The answer of the field at `lines[index]`: text after its label (and hint), plus any nested lines. */
function fieldValue(lines: string[], index: number): string {
  const line = lines[index];
  const m = line.match(FIELD_LINE);
  let inline: string;
  if (!m) {
    inline = line.split(':').slice(1).join(':');
  } else if (m[1].trim().endsWith(':')) {
    inline = m[2]; // `- **Label:** value`
  } else {
    // `- **Label** (hint, may contain "a: b" or nested parens): value`
    inline = m[2].replace(/^\s*(?:\((?:[^()]|\([^()]*\))*\))?\s*:?/, '');
  }
  return [inline, ...nestedLines(lines, index)].join('\n').trim();
}

function tiersIn(text: string): RiskTier[] {
  return RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(text));
}

function extractTier(body: string): RiskTier | null {
  // Skip the template's enum hint "(prohibited / high / limited / minimal)".
  const clean = (text: string) => text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
  const lines = body.split(/\r?\n/);
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const fieldIndex = lines.findIndex((l) => TIER_FIELD.test(l) || /^\s*[-*]\s*tier\b/i.test(l));
  if (fieldIndex === -1) {
    const cleaned = clean(body);
    const found = tiersIn(cleaned);
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      const inValue = tiersIn(cleaned.split(':').slice(1).join(':'));
      if (inValue.length === 1) return inValue[0];
    }
    return null;
  }

  const fieldLine = clean(lines[fieldIndex]);
  const onLine = tiersIn(fieldLine);
  if (onLine.length === 1) return onLine[0];
  if (onLine.length > 1) {
    // Ambiguous mention; prefer the value after a colon on the field line.
    const inValue = tiersIn(fieldLine.split(':').slice(1).join(':'));
    return inValue.length === 1 ? inValue[0] : null;
  }
  // No tier on the field line: the value sits on the lines indented below it.
  const nested = nestedLines(lines, fieldIndex).map(clean);
  const found = tiersIn(nested.join('\n'));
  if (found.length === 1) return found[0];
  // Ambiguous; the first nested line naming a tier wins (e.g. "limited" above "- not high because ...").
  for (const line of nested) {
    const inLine = tiersIn(line);
    if (inLine.length === 1) return inLine[0];
    if (inLine.length > 1) break;
  }
  return null;
}

function answeredText(body: string): string {
  const lines = body.split(/\r?\n/);
  const unanswered = unansweredFieldLines(lines);
  return lines
    .filter((_, i) => !unanswered.has(i))
    .join('\n')
    .trim();
}

function quote(line: string): string {
  const text = line.trim();
  return text.length > MAX_QUOTE ? `${text.slice(0, MAX_QUOTE - 1)}…` : text;
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const answered = answeredText(body);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const lines = body.split(/\r?\n/);
    for (const i of unansweredFieldLines(lines)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${lines[i].trim()}`,
        source: 'validator'
      });
    }
    for (const line of lines.filter((l) => NEEDS_HUMAN_INPUT.test(l))) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unresolved NEEDS HUMAN INPUT in "${check.title}": ${quote(line)}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffLine = body
          .split(/\r?\n/)
          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

